import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import pytest
from vardiya import vardiya_suresi_hesapla, haftalik_toplam

def test_normal_ayni_gun():
    assert vardiya_suresi_hesapla("09:00", "17:00", 60) == 420

def test_gece_vardiyasi():
    # 22:00 -> 06:00 = 480 dk, mola 60 => 420 (zaten 15'in katı)
    assert vardiya_suresi_hesapla("22:00", "06:00", 60) == 420

def test_esitlik_24_saat():
    assert vardiya_suresi_hesapla("08:00", "08:00", 0) == 1440

def test_esitlik_molali():
    # 24 saat = 1440, mola 60 => 1380, 15'in katı
    assert vardiya_suresi_hesapla("08:00", "08:00", 60) == 1380

def test_yuvarlama_ornegi_127_120():
    # 09:00 -> 11:07 = 127 dk, mola 0 => 120
    assert vardiya_suresi_hesapla("09:00", "11:07", 0) == 120

def test_yuvarlama_asagi():
    # 09:00 -> 10:10 = 70 dk => 60
    assert vardiya_suresi_hesapla("09:00", "10:10", 0) == 60

def test_mola_esit_ham_sifir():
    assert vardiya_suresi_hesapla("09:00", "10:00", 60) == 0

def test_mola_buyuk_sifir():
    assert vardiya_suresi_hesapla("09:00", "10:00", 120) == 0

def test_mola_aralik_disi():
    with pytest.raises(ValueError):
        vardiya_suresi_hesapla("09:00", "17:00", -1)
    with pytest.raises(ValueError):
        vardiya_suresi_hesapla("09:00", "17:00", 721)

def test_mola_sinir_gecerli():
    # 00:00 -> 12:30 = 750 dk, mola 720 => net 30 => 30
    assert vardiya_suresi_hesapla("00:00", "12:30", 720) == 30
    assert vardiya_suresi_hesapla("09:00", "10:00", 0) == 60

def test_bicim_hatali():
    for kotu in ["24:00", "23:60", "9:00", "09:0", "09-00", "0900", "", "12:00:00", " 09:00", "09:00 "]:
        with pytest.raises(ValueError):
            vardiya_suresi_hesapla(kotu, "17:00", 0)
        with pytest.raises(ValueError):
            vardiya_suresi_hesapla("09:00", kotu, 0)

def test_mola_tam_sayi_degil():
    with pytest.raises(TypeError):
        vardiya_suresi_hesapla("09:00", "17:00", "60")
    with pytest.raises(TypeError):
        vardiya_suresi_hesapla("09:00", "17:00", 60.0)

def test_haftalik_toplam():
    kayitlar = [("09:00", "11:07", 0), ("22:00", "06:00", 60)]
    # 120 + 420 = 540, 2 gün
    assert haftalik_toplam(kayitlar) == {"toplam_dakika": 540, "gun_sayisi": 2}

def test_haftalik_bos():
    assert haftalik_toplam([]) == {"toplam_dakika": 0, "gun_sayisi": 0}

def test_kayitlar_liste_degil():
    with pytest.raises(TypeError):
        haftalik_toplam("09:00")
    with pytest.raises(TypeError):
        haftalik_toplam((("09:00", "17:00", 60),))

def test_kayit_demet_uzunlugu():
    with pytest.raises(ValueError):
        haftalik_toplam([("09:00", "17:00")])
    with pytest.raises(ValueError):
        haftalik_toplam([("09:00", "17:00", 60, "fazla")])

def test_tek_vardiya_1440_asamaz():
    assert vardiya_suresi_hesapla("00:00", "00:00", 0) <= 1440
    assert vardiya_suresi_hesapla("00:00", "00:00", 0) == 1440

import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
from decimal import Decimal
import pytest
from kargo import desi_hesapla, ucret_hesapla, toplu_fiyatlandir

def test_desi_normal():
    assert desi_hesapla(30, 40, 50) == pytest.approx(20.0)

def test_desi_ham_deger_yuvarlanmamis():
    beklenen = 10 * 10 * 11 / 3000
    sonuc = desi_hesapla(10, 10, 11)
    assert sonuc == pytest.approx(beklenen, rel=1e-9)
    assert sonuc != round(beklenen, 3) or beklenen == round(beklenen, 3)
    assert isinstance(sonuc, float)

def test_desi_sinir_200_gecerli():
    assert desi_hesapla(200, 200, 200) == pytest.approx(200*200*200/3000)

def test_desi_sifir_hatasi():
    with pytest.raises(ValueError) as e:
        desi_hesapla(0, 10, 10)
    assert str(e.value) == "Geçersiz ölçü"

def test_desi_negatif_hatasi():
    with pytest.raises(ValueError) as e:
        desi_hesapla(10, -5, 10)
    assert str(e.value) == "Geçersiz ölçü"

def test_desi_200_ustu_hatasi():
    with pytest.raises(ValueError) as e:
        desi_hesapla(201, 10, 10)
    assert str(e.value) == "Geçersiz ölçü"

