    assert ucret_hesapla(5, 3, "Marmara") == Decimal("110.00")

def test_ucret_desi_buyuk():
    assert ucret_hesapla(3, 10, "Marmara") == Decimal("170.00")

def test_ucret_anadolu():
    assert ucret_hesapla(5, 3, "Anadolu") == Decimal("132.00")

def test_ucret_diger():
    assert ucret_hesapla(5, 3, "Diger") == Decimal("165.00")

def test_ucret_yarim_yukari_yuvarlama():
    assert ucret_hesapla(0.12375, 0, "Marmara") == Decimal("51.49")

def test_ucret_gecersiz_bolge():
    with pytest.raises(ValueError):
        ucret_hesapla(5, 3, "Ege")

def test_toplu_bos_liste():
    assert toplu_fiyatlandir([]) == []

def test_toplu_normal():
    paketler = [{"en": 30, "boy": 40, "yukseklik": 50, "kilo": 5, "bolge": "Marmara"}]
    assert toplu_fiyatlandir(paketler) == [Decimal("290.00")]

def test_toplu_eksik_anahtar():
    paketler = [{"en": 10, "boy": 10, "yukseklik": 10, "kilo": 1}]
    assert toplu_fiyatlandir(paketler) == [Decimal("-1")]

def test_toplu_gecersiz_olcu():
    paketler = [{"en": 0, "boy": 10, "yukseklik": 10, "kilo": 1, "bolge": "Marmara"}]
    assert toplu_fiyatlandir(paketler) == [Decimal("-1")]

def test_toplu_kilo_sinir_disi():
